def minZeroArray(nums, queries):
    n = len(nums)
    if all(x == 0 for x in nums):
        return 0
    # bits[i]: bit s set <=> sum s is reachable from queries (so far) covering index i
    bits = [1] * n
    masks = [(1 << (x + 1)) - 1 for x in nums]
    for k, (l, r, val) in enumerate(queries, 1):
        for i in range(l, r + 1):
            bits[i] = (bits[i] | (bits[i] << val)) & masks[i]
        if all((bits[i] >> nums[i]) & 1 for i in range(n)):
            return k
    return -1
